const cmds = [
"cat rust-toolchain.toml && cat Cargo.toml",
"for f in scripts/*.sh; do echo ===$f; cat \"$f\"; done",
"find examples -maxdepth 3 -type f \\( -name Cargo.toml -o -name '*.rs' -o -name '*.md' \\) | sort",
"rg -n '#\\[.*test|motsu|e2e|nitro|benchmark|criterion|iai|cargo test|cargo bench|cargo llvm-cov|cargo tarpaulin|wasm32|activate|deploy|assert_' --glob '*.rs' --glob '*.toml' --glob '*.yml' --glob '*.yaml' --glob '*.sh' --glob '*.md' ."
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:7000})));
for (let i=0;i<rs.length;i++){text(`--- ${i+1} ---\n${rs[i].output}`)}

