const r=await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
import re

def split_args(s):
    result=[]; start=0; depth=0
    for i,ch in enumerate(s):
        if ch in '<([': depth += 1
        elif ch in '>)]': depth -= 1
        elif ch==',' and depth==0:
            item=s[start:i].strip()
            if item: result.append(item)
            start=i+1
    item=s[start:].strip()
    if item: result.append(item)
    return result
count=0; addr=0; contracts=0; bad=[]
for p in Path('contracts/src').rglob('*.rs'):
 s=p.read_text()
 if '#[motsu::test]' not in s: continue
 start=s.find('#[cfg(test)]')
 region=s[start:]
 for m in re.finditer(r'#\[motsu::test\]',region):
  fn=re.search(r'\bfn\s+(\w+)\s*\(',region[m.end():])
  if not fn: bad.append((p,'fn not found')); continue
  fnname=fn.group(1); absopen=m.end()+fn.end()-1
  depth=1; j=absopen+1
  while depth and j<len(region):
   if region[j]=='(': depth+=1
   elif region[j]==')': depth-=1
   j+=1
  args=split_args(region[absopen+1:j-1])
  count+=1
  for arg in args:
   if ':' not in arg: bad.append((p,fnname,arg)); continue
   name,typ=map(str.strip,arg.split(':',1))
   if typ=='Address': addr+=1
   elif typ.startswith('Contract<') and typ.endswith('>'): contracts+=1
   else: bad.append((p,fnname,arg))
print(f'tests={count}, contract args={contracts}, address args={addr}, unexpected={len(bad)}')
for x in bad[:30]: print(x)
PY",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:1500});text(r.output);

