from pathlib import Path
import re

def split_args(s):
    out=[]; start=0; depth=0
    for i,ch in enumerate(s):
        if ch in '<([': depth += 1
        elif ch in '>)]': depth -= 1
        elif ch==',' and depth==0:
            value=s[start:i].strip()
            if value: out.append(value)
            start=i+1
    value=s[start:].strip()
    if value: out.append(value)
    return out

def transform(path):
    src=path.read_text()
    if '#[motsu::test]' not in src: return False
    test_start=src.find('#[cfg(test)]')
    if test_start < 0: raise RuntimeError(f'no test module: {path}')
    before, region=src[:test_start], src[test_start:]
    attrs=list(re.finditer(r'#\[motsu::test\]',region))
    for attr in reversed(attrs):
        fn=re.search(r'\bfn\s+(\w+)\s*\(',region[attr.end():])
        if not fn: raise RuntimeError(f'function not found in {path}')
        fn_name=fn.group(1)
        open_paren=attr.end()+fn.end()-1
        depth=1; close_paren=open_paren+1
        while depth and close_paren<len(region):
            if region[close_paren]=='(': depth+=1
            elif region[close_paren]==')': depth-=1
            close_paren+=1
        if depth: raise RuntimeError(f'unclosed function args {path}:{fn_name}')
        arg_text=region[open_paren+1:close_paren-1]
        args=split_args(arg_text)
        setup=[]
        for arg in args:
            name,typ=map(str.strip,arg.split(':',1))
            if typ=='Address':
                setup.append(f'let {name} = test_address(stringify!({name}));')
            elif typ.startswith('Contract<') and typ.endswith('>'):
                inner=typ[len('Contract<'):-1]
                setup.append(f'let {name} = TestContract::<{inner}>::new(stringify!({name}));')
            else: raise RuntimeError(f'unhandled arg {path}:{fn_name} {arg}')
        # Locate the opening brace after the optional return type.
        brace=region.find('{',close_paren)
        if brace<0: raise RuntimeError(f'function body missing {path}:{fn_name}')
        region=region[:open_paren+1]+region[close_paren-1:close_paren]+region[close_paren:]
        # The prior replacement above changes only the argument list to empty.
        # Recover the body brace after the shorter signature.
        new_close=open_paren+1
        brace=region.find('{',new_close)
        if setup:
            indent=re.search(r'\n(\s*)\S',region[brace+1:])
            body_indent=indent.group(1) if indent else '        '
            prelude='\n'+''.join(body_indent+line+'\n' for line in setup)
            region=region[:brace+1]+prelude+region[brace+1:]
    region=region.replace('use motsu::prelude::*;', 'use crate::test_support::{test_address, TestContract};')
    region=region.replace('use motsu::prelude::Contract;', 'use crate::test_support::{test_address, TestContract};')
    if 'use crate::test_support::' not in region:
        # Tests without a direct Motsu import still need the adapter names.
        mod_open=region.find('mod tests {')
        if mod_open<0: raise RuntimeError(f'test module not found {path}')
        at=mod_open+len('mod tests {')
        region=region[:at]+'\n    use crate::test_support::{test_address, TestContract};'+region[at:]
    region=region.replace('#[motsu::test]', '#[test]')
    region=re.sub(r'\bContract(?=\s*<)', 'TestContract', region)
    region=region.replace('Contract::<', 'TestContract::<')
    # Explicitly created test contracts also receive deterministic names.
    cursor=0
    while True:
        start=region.find('TestContract::',cursor)
        if start<0: break
        end=region.find('::new()', start)
        if end<0: cursor=start+len('TestContract::'); continue
        region=region[:end]+'::new("contract")'+region[end+len('::new()'):]
        cursor=end+len('::new("contract")')
    for old,new in [('motsu_expect_err','expect_err'),('motsu_unwrap_err','unwrap_err'),('motsu_expect','expect'),('motsu_unwrap','unwrap'),('motsu_res','')]:
        region=region.replace(old,new)
    path.write_text(before+region)
    return True

