        assert_eq!(U256::ZERO, contract.sender(alice).balance_of(alice));
        assert_eq!(U256::ZERO, contract.sender(alice).total_supply());

        // Initialize state for the test case:
        // Alice's balance as `U256::MAX`.
        contract
