            .motsu_expect("should construct");

        let one = uint!(1_U256);

        // Initialize state for the test case:
        // Alice's & Bob's balance as `one`.
        contract
            .sender(alice)
            .mint(alice, one)
            .motsu_expect("should mint tokens");

