    fn fallback() {
        let proxy = TestVMContract::<Erc1967ProxyExample>::new(stringify!(proxy));
        let logic = TestVMContract::<UUPSErc20Example>::new(stringify!(logic));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        logic.sender(alice).constructor();

        proxy
            .sender(alice)
            .constructor(logic.address())
            .expect("should be able to construct");

        // verify initial balance is [`U256::ZERO`].
        let balance_of_alice_call =
            ERC20Interface::balanceOfCall { account: alice }.abi_encode();
        let balance = proxy
            .sender(alice)
            .fallback(&balance_of_alice_call)
            .expect("should be able to get balance");
        assert_eq!(balance, U256::ZERO.abi_encode());

        let total_supply_call = ERC20Interface::totalSupplyCall {}.abi_encode();
        let total_supply = proxy
            .sender(alice)
            .fallback(&total_supply_call)
            .expect("should be able to get total supply");
        assert_eq!(total_supply, U256::ZERO.abi_encode());

        // mint 1000 tokens.
        let amount = U256::from(1000);

        let mint_call =
            ERC20Interface::mintCall { to: alice, value: amount }.abi_encode();
        proxy
            .sender(alice)
            .fallback(&mint_call)
            .expect("should be able to mint");

        proxy.assert_emitted(&erc20::Transfer {
            from: Address::ZERO,
            to: alice,
            value: amount,
        });

        // check that the balance can be accurately fetched through the proxy.
        let balance = proxy
            .sender(alice)
            .fallback(&balance_of_alice_call)
            .expect("should be able to get balance");
        assert_eq!(balance, amount.abi_encode());
        let alice = test_address(stringify!(alice));

        let tokens = 4;
        let token_ids = random_token_ids(tokens);

        contract.sender(alice).constructor(erc721_contract.address());

        for token_id in &token_ids {
            erc721_contract
                .sender(alice)
                ._mint(alice, *token_id)
                .expect("should mint {token_id} for {alice}");

            erc721_contract
                .sender(alice)
                .approve(contract.address(), *token_id)
                .expect(
                    "should approve {token_id} for {contract.address()}",
                );
        }

        assert!(contract
            .sender(alice)
            .deposit_for(alice, token_ids.clone())
            .expect("should deposit"));

        let initial_balance =
            erc721_contract.sender(alice).balance_of(alice).unwrap();
        let initial_wrapped_balance =
            contract.sender(alice).erc721.balance_of(alice).unwrap();

        let initial_contract_balance = erc721_contract
            .sender(alice)
            .balance_of(contract.address())
            .unwrap();

        assert!(contract
            .sender(alice)
            .withdraw_to(alice, token_ids.clone())
            .expect("should withdraw"));

        for token_id in token_ids {
            erc721_contract.assert_emitted(&erc721::Transfer {
                from: contract.address(),
                to: alice,
                token_id,
            });

            contract.assert_emitted(&erc721::Transfer {
                from: alice,
                to: Address::ZERO,
                token_id,
            });
        }

        assert_eq!(
            erc721_contract.sender(alice).balance_of(alice).unwrap(),
            initial_balance + U256::from(tokens)
        );

        assert_eq!(
            contract.sender(alice).erc721.balance_of(alice).unwrap(),
            initial_wrapped_balance - U256::from(tokens)
        );

        assert_eq!(
            erc721_contract
