fn withdraw_to_reverts_when_insufficient_balance() {
    let contract = TestVMContract::<Erc20WrapperTestExample>::new(stringify!(contract));
    let erc20_contract = TestVMContract::<Erc20>::new(stringify!(erc20_contract));
    let alice = test_address(stringify!(alice));

    let amount = uint!(10_U256);

    contract
        .sender(alice)
        .constructor(erc20_contract.address())
        .expect("should construct");

    erc20_contract
        .sender(alice)
        ._mint(alice, amount)
        .expect("should mint");

    erc20_contract
        .sender(alice)
        .approve(contract.address(), amount)
        .expect("should approve");

    contract
        .sender(alice)
        .deposit_for(alice, amount)
        .expect("should deposit");

    let exceeding_value = amount + uint!(1_U256);

    let err = contract
        .sender(alice)
        .withdraw_to(alice, exceeding_value)
        .expect_err("should return Error::SafeErc20");

    assert!(matches!(
        err,
        Error::InsufficientBalance(
            erc20::ERC20InsufficientBalance {
                sender,
                balance,
                needed
            }
        ) if sender == alice && balance == amount && needed == exceeding_value
    ));
}

