#[test]
fn deposit_for_reverts_when_invalid_receiver() {
    let contract = TestVMContract::<Erc20WrapperTestExample>::new(stringify!(contract));
    let erc20_contract = TestVMContract::<Erc20>::new(stringify!(erc20_contract));
    let alice = test_address(stringify!(alice));

    let invalid_receiver = contract.address();

    contract
        .sender(alice)
        .constructor(erc20_contract.address())
        .expect("should construct");

    let err = contract
        .sender(alice)
        .deposit_for(invalid_receiver, uint!(10_U256))
        .expect_err("should return Error::InvalidReceiver");

    assert!(matches!(
        err,
        Error::InvalidReceiver(erc20::ERC20InvalidReceiver { receiver }) if receiver == invalid_receiver
    ));
}

