    fn renounce_ownership() {
        let beacon = TestVMContract::<UpgradeableBeacon>::new(stringify!(beacon));
        let erc20 = TestVMContract::<Erc20>::new(stringify!(erc20));
        let erc20_2 = TestVMContract::<Erc20>::new(stringify!(erc20_2));
        let alice = test_address(stringify!(alice));

        beacon.sender(alice).constructor(erc20.address(), alice).unwrap();

        // renounce ownership.
        beacon
            .sender(alice)
            .renounce_ownership()
            .expect("should be able to renounce ownership");

        let owner = beacon.sender(alice).owner();
        assert_eq!(owner, Address::ZERO);

        // no one should be able to upgrade now.
        let err = beacon
            .sender(alice)
            .upgrade_to(erc20_2.address())
            .expect_err("should fail when no owner exists");

        assert!(matches!(
