def masked(s):
    # Preserve offsets and braces while blanking Rust comments and quoted strings.
    out=list(s); i=0; n=len(s); state='code'; depth=0
    while i<n:
        if state=='code':
            if s.startswith('//',i): out[i]=out[i+1]=' ';i+=2;state='line';continue
            if s.startswith('/*',i): out[i]=out[i+1]=' ';i+=2;state='block';depth=1;continue
            if s.startswith('r#',i):
                j=i+1
                while j<n and s[j]=='#':j+=1
                if j<n and s[j]=='"':
                    hashes=j-(i+1); end='"'+'#'*hashes
                    for k in range(i,j+1):out[k]=' '
                    i=j+1;state='raw';rawend=end;continue
            if s[i]=='"':out[i]=' ';i+=1;state='string';continue
            i+=1
        elif state=='line':
            if s[i]=='\n':state='code'
            else:out[i]=' '
            i+=1
        elif state=='block':
            if s.startswith('/*',i):out[i]=out[i+1]=' ';i+=2;depth+=1
            elif s.startswith('*/',i):out[i]=out[i+1]=' ';i+=2;depth-=1;state='code' if depth==0 else 'block'
            else:
                if s[i]!='\n':out[i]=' '
                i+=1
        elif state=='string':
            if s[i]=='\\':out[i]=' ';i+=1
            elif s[i]=='"':out[i]=' ';i+=1;state='code'
            else:
                if s[i]!='\n':out[i]=' '
                i+=1
        elif state=='raw':
            if s.startswith(rawend,i):
                for k in range(i,i+len(rawend)):out[k]=' '
                i+=len(rawend);state='code'
            else:
                if s[i]!='\n':out[i]=' '
                i+=1
    return ''.join(out)

def get_tests(ref):
    paths=subprocess.check_output(['git','ls-tree','-r','--name-only',ref,'examples'],text=True).splitlines()
    result=collections.defaultdict(list)
    for p in paths:
        if '/tests/' not in p or not p.endswith('.rs'):continue
        s=source(ref,p); msk=masked(s)
        for ma in ATTR.finditer(msk):
            f=FN.search(msk,ma.end())
            if not f or f.start()-ma.end()>250:continue
            op=msk.find('{',f.end())
            if op<0:continue
            d=0; end=None
            for i in range(op,len(msk)):
                if msk[i]=='{':d+=1
                elif msk[i]=='}':
                    d-=1
                    if d==0:end=i+1;break
            if end is None:continue
            body=s[op:end]
            features={
              'asserts':len(re.findall(r'\bassert(?:_eq|_ne|_matches)?\s*!',body)),
              'watch':len(re.findall(r'\bwatch\s*!',body)),
              'send':len(re.findall(r'\bsend\s*!',body)),
              'receipt':len(re.findall(r'\breceipt\s*!',body)),
              'revert_match':len(re.findall(r'\.reverted_with\s*\(',body)),
              'expect_err':len(re.findall(r'\.expect_err\s*\(',body)),
              'is_ok':len(re.findall(r'\.is_ok\s*\(',body)),
              'is_err':len(re.findall(r'\.is_err\s*\(',body)),
            }
            result[(p,f.group(1))].append((body,features))
    return result
